use std::{fs::File,collections::{BTreeMap,BTreeSet},time::Instant};
use viewer_core::DatasetSource;
use viewer_format::{FormatReader,PagedReader,OctreeReader};
use viewer_render_wgpu::{CellGrid, representative_depth,representative_depth_for_spacing};
fn main()->Result<(),Box<dyn std::error::Error>> {
 let start=Instant::now();let path=std::env::args_os().nth(1).unwrap();let mut reader=FormatReader::new(File::open(&path)?)?;let mut attrs=path.clone();attrs.push("attrs");if !reader.has_attributes(){reader.attach_attributes(File::open(attrs)?)?;}
 let mut flags=BTreeMap::new();let mut paged=PagedReader::open(File::open(&path)?)?;let mut pages=vec![paged.root_page().clone()];let mut i=0;while i<pages.len(){for n in pages[i].nodes(){if flags.insert(n.id(),!n.has_children()).is_some(){return Err("duplicate node".into());}}let children:Vec<_>=pages[i].child_pages().collect();for(a,p)in children{pages.push(paged.read_child_page(a,p)?);}i+=1;}
 let dataset=reader.format_metadata().viewer_dataset()?;let hierarchy=dataset.hierarchy().clone();let root=hierarchy.stats().root_bounds;let origin=dataset.coordinate_frame().origin();let root_side=(0..3).map(|a|root.max()[a]-root.min()[a]).fold(0.0,f64::max);let grid=CellGrid{root_min:std::array::from_fn(|a|root.min()[a]-origin[a]),root_side};
 let(mut leaves,mut total_points,mut flagged,mut candidate_points,mut scanned_points,mut finite,mut nonfinite,mut actual_over_nodes,mut actual_over_points,mut skipped)=(0u64,0u64,0u64,0u64,0u64,0u64,0u64,0u64,0u64,0u64);
 let(mut point_hist,mut span_hist,mut actual_hist,mut unique_hist,mut depths)=(BTreeMap::<u64,u64>::new(),BTreeMap::<u32,u64>::new(),BTreeMap::<u32,u64>::new(),BTreeMap::<usize,u64>::new(),BTreeMap::<u8,u64>::new());
 let mut visited=BTreeSet::new();
 for node in hierarchy.query(root){visited.insert(node.id());let leaf=*flags.get(&node.id()).ok_or("missing authoritative flag")?;if !leaf {continue;}leaves+=1;total_points+=node.point_count();let b=node.bounds();let min:[f64;3]=std::array::from_fn(|a|b.min()[a]-origin[a]);let max:[f64;3]=std::array::from_fn(|a|b.max()[a]-origin[a]);let local=viewer_core::SpatialBounds::new(min,max)?;let depth=node.spacing().map_or_else(||representative_depth(&grid,local),|s|representative_depth_for_spacing(&grid,s));let count=1u64<<depth;let side=grid.root_side/count as f64;
 let ranges:[(u64,u64);3]=std::array::from_fn(|a|{let last=(count-1)as f64;let lo=((min[a]-grid.root_min[a])/side).round().clamp(0.,last);let hi=(((max[a]-grid.root_min[a])/side).round()-1.).clamp(lo,last);(lo as u64,hi as u64)});let span_bits=ranges.iter().map(|(lo,hi)|64-(hi-lo).leading_zeros()).max().unwrap();if span_bits<=21{continue;}
 flagged+=1;candidate_points+=node.point_count();*point_hist.entry(node.point_count()).or_default()+=1;*span_hist.entry(span_bits).or_default()+=1;*depths.entry(depth).or_default()+=1;
 if scanned_points+node.point_count()>10_000_000||start.elapsed().as_secs()>180{skipped+=1;continue;}
 let(mut local_total,mut local_finite,mut local_over,mut local_bits)=(0u64,0u64,0u64,0u32);let mut unique=BTreeSet::new();let mut pos_min=[u64::MAX;3];let mut pos_max=[0u64;3];
 for id in node.blocks(){let block=reader.read_block(*id)?;for point in block.points().points(){local_total+=1;if !point.position.iter().all(|v|v.is_finite()){nonfinite+=1;continue;}local_finite+=1;unique.insert(point.position.map(|v|if v==0.0{0}else{v.to_bits()}));let coord:[u64;3]=std::array::from_fn(|a|(((f64::from(point.position[a])-grid.root_min[a])/grid.root_side*count as f64).floor().clamp(ranges[a].0 as f64,ranges[a].1 as f64))as u64);let relative:[u64;3]=std::array::from_fn(|a|coord[a]-ranges[a].0);let bits=relative.iter().map(|x|64-x.leading_zeros()).max().unwrap();local_bits=local_bits.max(bits);if bits>21{local_over+=1;}for a in 0..3{pos_min[a]=pos_min[a].min(relative[a]);pos_max[a]=pos_max[a].max(relative[a]);}}}
 scanned_points+=local_total;finite+=local_finite;actual_over_nodes+=u64::from(local_over>0);actual_over_points+=local_over;*actual_hist.entry(local_bits).or_default()+=1;*unique_hist.entry(unique.len()).or_default()+=1;
 println!("node={} depth={} spacing={:?} metadata_points={} decoded={} finite={} unique={} span_bits={} actual_max_bits={} actual_over21_points={} occupied_min={:?} occupied_max={:?}",node.id().get(),depth,node.spacing(),node.point_count(),local_total,local_finite,unique.len(),span_bits,local_bits,local_over,pos_min,pos_max);
 }
 if visited.len()!=flags.len()||visited.iter().any(|n|!flags.contains_key(n)){return Err("traversal mismatch".into());}
 println!("SUMMARY path={:?} authoritative_nodes={} leaves={} leaf_metadata_points={} initial_span_over21_nodes={} candidate_metadata_points={} scanned_points={} finite={} nonfinite={} actual_over21_nodes={} actual_over21_points={} skipped_nodes={}",path,flags.len(),leaves,total_points,flagged,candidate_points,scanned_points,finite,nonfinite,actual_over_nodes,actual_over_points,skipped);
 println!("candidate_points_hist={:?}\nspan_bits_hist={:?}\nactual_max_bits_hist={:?}\nunique_positions_hist={:?}\nabsolute_depth_hist={:?}",point_hist,span_hist,actual_hist,unique_hist,depths);Ok(())
}